{
  "title": "Detect DNS TXT Exfiltration via High Frequency Queries",
  "id": "rule-2026-001",
  "description": "Detects a high rate of DNS TXT record queries to a single external domain, indicative of DNS tunneling for data exfiltration.",
  "status": "experimental",
  "author": "SOC Team",
  "logsource": {
    "product": "dns",
    "service": "bind"
  },
  "detection": {
    "selection": {
      "eventtype": "query",
      "querytype": "TXT"
    },
    "groupby": {
      "field": "query.domain",
      "threshold": 300,
      "timeframe": "5m"
    },
    "condition": "selection and groupby"
  },
  "fields": ["src_ip", "query.domain", "query.type"],
  "falsepositives": ["Legitimate high-volume DNS TXT usage"],
  "level": "high"
}
